export async function runSearchReindexJob(orgId: OrgId): Promise<JobResult> {
  return runJob("search-reindex", async (result) => {
    // Replace this workspace's index so deleted comments, archived issues
    // and a second run cannot leave stale or duplicate documents behind.
    await searchRepo.deleteSearchDocumentsForOrg(orgId);

    await forEachPage(
      (cursor) =>
        projectRepo.listProjects({
          orgId,
          limit: PAGE_SIZE,
          cursor,
        }),
      async (project) => {
        try {
          await indexProject(orgId, project);
          result.processed += 1;
        } catch (error) {
          result.failed += 1;
          logger.error("failed to index project", {
            projectId: project.id,
            reason: error instanceof Error ? error.message : String(error),
          });
        }
      },
    );

    await forEachPage(
      (cursor) =>
        issueRepo.listIssues({
          orgId,
          limit: PAGE_SIZE,
          cursor,
        }),
      async (issue) => {
        try {
          await indexIssue(orgId, issue);
          result.processed += 1;

          await forEachPage(
            (cursor) =>
              commentRepo.listComments({
                orgId,
                issueId: issue.id,
                limit: PAGE_SIZE,
                cursor,
              }),
            async (comment) => {
              await indexComment(orgId, comment);
              result.processed += 1;
            },
          );
        } catch (error) {
          result.failed += 1;
          logger.error("failed to index issue", {
            issueId: issue.id,
            reason: error instanceof Error ? error.message : String(error),
          });
        }
      },
    );
  });
}

async function forEachPage<T>(
  fetchPage: (cursor: string | null) => Promise<Page<T>>,
  handle: (item: T) => Promise<void>,
): Promise<void> {
  let cursor: string | null = null;
  do {
    const page = await fetchPage(cursor);
    for (const item of page.items) {
      await handle(item);
    }
    cursor = page.nextCursor;
  } while (cursor !== null);
}

